import React, { useEffect, useState } from 'react';
import { Pressable, StyleSheet, Text, TextInput, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useTranslation } from 'react-i18next';
import { PrimaryButton } from '../components/PrimaryButton';
import { rideDispatchService } from '../services/rideDispatch';
import { formatFare } from '../utils/format';
import { colors, fontFamily, fontSize, radii, shadows } from '../theme';

type PaymentStatus = 'pending' | 'declared' | 'confirmed' | 'not_required';
const issueReasons = ['paid_but_not_received', 'incorrect_fare', 'upi_problem', 'cash_dispute', 'other'] as const;

export function CustomerRideSettlement({ rideId, fare, captainName, paymentStatus, freeRide, onHome }: { rideId: string; fare: number; captainName: string; paymentStatus: PaymentStatus; freeRide: boolean; onHome: () => void }) {
  const { t } = useTranslation(); const [method, setMethod] = useState<'cash' | 'upi' | null>(null); const [status, setStatus] = useState<PaymentStatus>(paymentStatus); const [showRating, setShowRating] = useState(freeRide || paymentStatus === 'not_required'); const [rating, setRating] = useState(0); const [note, setNote] = useState(''); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [issueOpen, setIssueOpen] = useState(false); const [issueReason, setIssueReason] = useState<typeof issueReasons[number] | null>(null); const [issueDetail, setIssueDetail] = useState(''); const [issueNoted, setIssueNoted] = useState(false);
  useEffect(() => rideDispatchService.subscribeToRide(rideId, (ride) => setStatus(ride.payment_status ?? 'pending'), () => setError(t('login.tryAgain'))), [rideId, t]);
  const declareMethod = async (selectedMethod: 'cash' | 'upi') => { setMethod(selectedMethod); setSaving(true); setError(''); try { const ride = await rideDispatchService.confirmCustomerPayment(rideId, selectedMethod); setStatus(ride.payment_status ?? 'declared'); } catch { setError(t('login.tryAgain')); } finally { setSaving(false); } };
  const submitIssue = async () => { if (!issueReason) return setError(t('rides.paymentIssueRequired')); if (issueReason === 'other' && !issueDetail.trim()) return setError(t('rides.paymentIssueDetailsRequired')); setSaving(true); setError(''); try { await rideDispatchService.raiseCustomerPaymentIssue(rideId, issueReason, issueDetail); setIssueOpen(false); setIssueNoted(true); } catch { setError(t('rides.paymentIssueSaveFailed')); } finally { setSaving(false); } };
  const submitRating = async (skip = false) => { if (!skip && !rating) return setError(t('rides.ratingRequired')); setSaving(true); setError(''); try { if (!skip) await rideDispatchService.rateCaptain(rideId, rating, note); onHome(); } catch { setError(t('rides.ratingSaveFailed')); } finally { setSaving(false); } };
  const readyForRating = showRating;
  return <SafeAreaView style={styles.safe}><View style={[styles.card, shadows.card]}>{!readyForRating ? <><Text style={styles.title}>{t('rides.summaryTitle')}</Text><Text style={styles.subtitle}>{t('rides.summaryWithCaptain', { captain: captainName })}</Text><View style={styles.fare}><Text style={styles.fareLabel}>{t('rides.totalDue')}</Text><Text style={styles.fareValue}>{formatFare(fare)}</Text></View>{status === 'pending' ? <><Text style={styles.sectionTitle}>{t('rides.paymentTitle')}</Text><Text style={styles.helper}>{t('rides.paymentDeclarationHint')}</Text><View style={styles.methods}>{(['upi', 'cash'] as const).map((value) => <Pressable key={value} onPress={() => { void declareMethod(value); }} disabled={saving} style={[styles.method, method === value && styles.methodSelected]}><Text style={styles.methodText}>{value === 'upi' ? 'UPI' : t('rides.cash')}</Text></Pressable>)}</View></> : <Text style={styles.helper}>{status === 'confirmed' ? t('rides.paymentConfirmed') : t('rides.awaitingCaptainPaymentConfirmation')}</Text>}{!issueNoted && <><PrimaryButton label={t('actions.continue')} onPress={() => setShowRating(true)} disabled={status !== 'confirmed'} /><Pressable onPress={() => { setIssueOpen(!issueOpen); setError(''); }} style={styles.issueButton}><Text style={styles.issueText}>{t('rides.raisePaymentIssue')}</Text></Pressable>{issueOpen && <View style={styles.issueCard}>{issueReasons.map((reason) => <Pressable key={reason} onPress={() => setIssueReason(reason)} style={styles.issueOption}><Text style={styles.issueRadio}>{issueReason === reason ? '◉' : '○'}</Text><Text style={styles.issueOptionText}>{t(`rides.paymentIssue${reason.split('_').map((part) => part[0].toUpperCase() + part.slice(1)).join('')}`)}</Text></Pressable>)}{issueReason === 'other' && <TextInput value={issueDetail} onChangeText={setIssueDetail} placeholder={t('rides.paymentIssueDetailsPlaceholder')} placeholderTextColor={colors.textMuted} multiline maxLength={500} style={styles.note} />}<PrimaryButton label={saving ? t('login.pleaseWait') : t('rides.submitPaymentIssue')} onPress={() => { void submitIssue(); }} disabled={saving} small /></View>}</>}{issueNoted && <><Text style={styles.noted}>{t('rides.paymentIssueNoted')}</Text><PrimaryButton label={t('actions.done')} onPress={onHome} /></>}{!!error && <Text style={styles.error}>{error}</Text>}</> : <><Text style={styles.emoji}>{freeRide ? '🎉' : '⭐'}</Text><Text style={styles.title}>{freeRide ? t('rides.freeRideTitle') : t('rides.rateCaptainTitle')}</Text>{freeRide && <Text style={styles.subtitle}>{t('rides.freeRideSummary')}</Text>}<Text style={styles.subtitle}>{t('rides.rateCaptainSubtitle', { captain: captainName })}</Text><View style={styles.stars}>{[1,2,3,4,5].map((star) => <Pressable key={star} onPress={() => { setRating(star); setError(''); }}><Text style={[styles.star, star <= rating && styles.starActive]}>★</Text></Pressable>)}</View><TextInput value={note} onChangeText={setNote} placeholder={t('rides.ratingNotePlaceholder')} placeholderTextColor={colors.textMuted} multiline maxLength={280} style={styles.note} />{!!error && <Text style={styles.error}>{error}</Text>}<PrimaryButton label={saving ? t('login.pleaseWait') : t('rides.submitRating')} onPress={() => { void submitRating(); }} disabled={saving || rating === 0} /><Pressable onPress={() => { void submitRating(true); }} style={styles.skip}><Text style={styles.skipText}>{t('rides.skipRating')}</Text></Pressable></>}</View></SafeAreaView>;
}
const styles = StyleSheet.create({ safe: { backgroundColor: colors.primaryLight, flex: 1, justifyContent: 'center', padding: 20 }, card: { backgroundColor: colors.surface, borderRadius: radii.xl, gap: 15, padding: 22 }, emoji: { fontSize: 48, textAlign: 'center' }, title: { color: colors.textPrimary, fontFamily, fontSize: fontSize.xl, fontWeight: '900', textAlign: 'center' }, subtitle: { color: colors.textSecondary, fontFamily, fontSize: fontSize.md, textAlign: 'center' }, helper: { color: colors.textMuted, fontFamily, fontSize: fontSize.sm, textAlign: 'center' }, fare: { alignItems: 'center', backgroundColor: colors.primaryLight, borderRadius: radii.lg, gap: 4, padding: 16 }, fareLabel: { color: colors.textSecondary, fontFamily, fontSize: fontSize.sm }, fareValue: { color: colors.primary, fontFamily, fontSize: 30, fontWeight: '900' }, sectionTitle: { color: colors.textPrimary, fontFamily, fontSize: fontSize.md, fontWeight: '900' }, methods: { flexDirection: 'row', gap: 10 }, method: { alignItems: 'center', borderColor: colors.border, borderRadius: radii.md, borderWidth: 1, flex: 1, padding: 15 }, methodSelected: { backgroundColor: colors.primaryLight, borderColor: colors.primary, borderWidth: 2 }, methodText: { color: colors.textPrimary, fontFamily, fontSize: fontSize.md, fontWeight: '900' }, stars: { flexDirection: 'row', justifyContent: 'center' }, star: { color: colors.border, fontSize: 42 }, starActive: { color: '#F59E0B' }, note: { borderColor: colors.border, borderRadius: radii.md, borderWidth: 1, color: colors.textPrimary, fontFamily, minHeight: 88, padding: 12, textAlignVertical: 'top' }, error: { color: colors.error, fontFamily, fontSize: fontSize.sm, fontWeight: '700', textAlign: 'center' }, skip: { alignItems: 'center', padding: 6 }, skipText: { color: colors.primary, fontFamily, fontSize: fontSize.md, fontWeight: '800' }, issueButton: { alignItems: 'center', padding: 5 }, issueText: { color: colors.primary, fontFamily, fontWeight: '800' }, issueCard: { gap: 8 }, issueOption: { alignItems: 'center', flexDirection: 'row', gap: 8 }, issueRadio: { color: colors.primary, fontSize: 20 }, issueOptionText: { color: colors.textPrimary, flex: 1, fontFamily, fontSize: fontSize.sm }, noted: { color: colors.success, fontFamily, fontSize: fontSize.sm, fontWeight: '700', lineHeight: 20, textAlign: 'center' } });
